65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final HttpServletRequest request;
83	
84	    /**
85	     * HTTP header carrying the client-supplied idempotency key for the create endpoint. When a
86	     * create repeats with a key already seen, the originally created owner is returned instead of
87	     * creating a duplicate.
88	     */
89	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
90	
91	    /**
92	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that key's create produced,
93	     * so a repeat create with the same key can return the originally created owner rather than
94	     * persisting a duplicate. Shared across requests, hence concurrency-safe.
95	     */
96	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
97	
98	    /**
99	     * Source of the {@code seq} carried by each structured {@code OWNER_CREATED} audit event: a
100	     * monotonically increasing integer stamped once per successful create, in creation order.
101	     * Shared across requests, hence concurrency-safe.
102	     */
103	    private static final AtomicLong OWNER_CREATED_SEQ = new AtomicLong(0);
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper,
109	                                 HttpServletRequest request) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	        this.request = request;
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
120	        Collection<Owner> owners;
121	        if (lastName != null) {
122	            owners = this.clinicService.findOwnerByLastName(lastName);
123	        } else {
124	            owners = this.clinicService.findAllOwners();
125	        }
126	        if (owners.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return okOwnerResponse(owner);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        String idempotencyKey = idempotencyKey();
146	        if (idempotencyKey != null) {
147	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
148	            if (replay != null) {
149	                return replay;
150	            }
151	        }
152	        Owner owner = createOwner(ownerFieldsDto);
153	        if (idempotencyKey != null) {
154	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
155	        }
156	        return createdOwnerResponse(owner);
157	    }
158	
159	    /**
160	     * Reads the request's {@code Idempotency-Key} header, returning the trimmed key or {@code null}
161	     * when the header is absent or blank. A blank key carries no intent to deduplicate, so the
162	     * create proceeds normally.
163	     *
164	     * @return the non-blank idempotency key, or {@code null} when none was supplied
165	     */
166	    private String idempotencyKey() {
167	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
168	        if (key == null || key.isBlank()) {
169	            return null;
170	        }
171	        return key.trim();
172	    }
173	
174	    /**
175	     * Replays the create originally produced by the given {@code Idempotency-Key}, if any: when the
176	     * key has already created an owner that still exists, that owner is rendered with {@code 200 OK}
177	     * (rather than creating a duplicate with {@code 201 Created}). When the key has not been seen, or
178	     * the owner it created no longer exists, {@code null} is returned so the caller creates the owner
179	     * normally.
180	     *
181	     * @param idempotencyKey the non-blank idempotency key supplied on the request
182	     * @return the {@code 200 OK} response carrying the originally created owner, or {@code null}
183	     */
184	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
185	        Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
186	        if (existingId == null) {
187	            return null;
188	        }
189	        Owner existing = this.clinicService.findOwnerById(existingId);
190	        if (existing == null) {
191	            return null;
192	        }
193	        return okOwnerResponse(existing);
194	    }
195	
196	    /**
197	     * Runs the full intake pipeline for a newly submitted owner and persists the result, returning
198	     * the saved {@link Owner}. The submitted fields are normalized and validated
199	     * ({@link #prepareNewOwner(OwnerFieldsDto, LocalDate)}) against the effective business-day
200	     * {@code registrationDate} ({@link #effectiveRegistrationDate(OwnerFieldsDto)}); the owner is
201	     * then mapped, stamped with that registration date and every derived value (member id,
202	     * namesake count, household), flagged as a possible duplicate where applicable, saved, and
203	     * finally stamped with its household member count. A rule that rejects the owner signals it by
204	     * throwing, which the exception advice renders as the matching 4xx response, so this method
205	     * returns only for an owner that was accepted and persisted. The create is audited once the
206	     * owner has its identity.
207	     *
208	     * <p>The returned owner carries its generated id and every stored field, ready to be rendered by
209	     * {@link #createdOwnerResponse(Owner)}.
210	     *
211	     * @param ownerFieldsDto the submitted owner fields, normalized in place
212	     * @return the persisted owner
213	     */
214	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
215	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
216	        prepareNewOwner(ownerFieldsDto, registrationDate);
217	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
218	        owner.setRegistrationDate(registrationDate);
219	        owner.setMemberId(memberIdFor(owner));
220	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
221	        assignHousehold(owner);
222	        applyPossibleDuplicate(owner, ownerFieldsDto);
223	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
224	        this.clinicService.saveOwner(owner);
225	        applyHouseholdMemberCount(owner);
226	        auditOwnerCreated(owner);
227	        emitOwnerCreatedEvent(owner);
228	        return owner;
229	    }
230	
231	    /**
232	     * Writes the human-readable {@code Owner created} audit line for a freshly persisted owner,
233	     * carrying its {@code id}, its unified {@code memberId}, its stored {@code registrationDate} and
234	     * its derived {@code membershipLevel}. This is the free-form companion to the structured
235	     * {@code OWNER_CREATED} event (see {@link #emitOwnerCreatedEvent(Owner)}); isolating it here
236	     * keeps {@link #createOwner(OwnerFieldsDto)} a thin orchestration and gives the audit line one
237	     * place to grow.
238	     *
239	     * @param owner the persisted owner, already carrying its generated id and derived values
240	     */
241	    private void auditOwnerCreated(Owner owner) {
242	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
243	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
244	            owner.getMembershipLevel());
245	    }
246	
247	    /**
248	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner,
249	     * alongside the human-readable audit line. The event is a JSON object carrying, in order, a
250	     * {@code seq} (a monotonically increasing integer across creates, see {@link #OWNER_CREATED_SEQ}),
251	     * the owner's {@code ownerId}, the owner's current primary identifier (see
252	     * {@link #primaryIdentifier(Owner)}) under the {@code memberId} key, the owner's derived
253	     * {@code membershipLevel}, and the {@code event} marker {@code 'OWNER_CREATED'}. Published to the
254	     * dedicated {@code AUDIT} logger so downstream consumers can react to owner creation structurally
255	     * rather than by parsing the free-form line.
256	     *
257	     * @param owner the persisted owner, already carrying its generated id and derived values
258	     */
259	    private void emitOwnerCreatedEvent(Owner owner) {
260	        long seq = OWNER_CREATED_SEQ.incrementAndGet();
261	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":{},\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
262	            seq, owner.getId(), jsonString(primaryIdentifier(owner)), owner.getMembershipLevel());
263	    }
264	
265	    /**
266	     * Returns the owner's current primary identifier, the single identity the structured
267	     * {@code OWNER_CREATED} event carries: the owner's unified {@code memberId}. This is the one seam
268	     * that decides which field is primary, so the event carries the member id under its
269	     * {@code memberId} key.
270	     *
271	     * @param owner the persisted owner whose primary identifier the event should carry
272	     * @return the owner's current primary identifier
273	     */
274	    private String primaryIdentifier(Owner owner) {
275	        return owner.getMemberId();
276	    }
277	
278	    /**
279	     * Renders a value as a JSON string literal for the structured audit event: {@code null} becomes
280	     * the JSON {@code null} keyword, otherwise the value is quoted with the JSON-significant
281	     * characters ({@code "} and {@code \}) escaped. The derived identifiers this carries never contain
282	     * such characters, but escaping keeps the emitted event valid JSON regardless.
283	     *
284	     * @param value the value to render, or {@code null}
285	     * @return the JSON representation of the value
286	     */
287	    private String jsonString(String value) {
288	        if (value == null) {
289	            return "null";
290	        }
291	        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
292	    }
293	
294	    /**
295	     * Renders a persisted owner as the {@code 201 Created} response of the create endpoint. The owner
296	     * is mapped to an {@link OwnerDto}, its {@code bulkSignupWarning} is derived from the owner's
297	     * stored {@code registrationDate} (mirroring {@link #getOwner(Integer)}), and a {@code Location}
298	     * header pointing at {@code /api/owners/{id}} is attached. Isolating the response assembly here
299	     * keeps {@link #addOwner(OwnerFieldsDto)} a thin orchestration of "create the owner, then render
300	     * it" and gives the created representation one place to grow.
301	     *
302	     * @param owner the persisted owner to render, carrying its generated id and stored fields
303	     * @return the {@code 201 Created} response carrying the owner representation and {@code Location} header
304	     */
305	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
306	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
307	        HttpHeaders headers = new HttpHeaders();
308	        headers.setLocation(UriComponentsBuilder.newInstance()
309	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
310	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
311	    }
312	
313	    /**
314	     * Renders a persisted owner as the {@code 200 OK} response shared by the read path
315	     * ({@link #getOwner(Integer)}) and the idempotent-replay path
316	     * ({@link #replayIdempotentCreate(String)}): the owner is stamped with its household member
317	     * count and then mapped to an {@link OwnerDto} carrying its {@code bulkSignupWarning} (see
318	     * {@link #toOwnerDtoWithWarning(Owner)}). Isolating the assembly here keeps both paths rendering
319	     * an existing owner identically rather than each copying the same steps.
320	     *
321	     * @param owner the persisted owner to render
322	     * @return the {@code 200 OK} response carrying the owner representation
323	     */
324	    private ResponseEntity<OwnerDto> okOwnerResponse(Owner owner) {
325	        applyHouseholdMemberCount(owner);
326	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
327	    }
328	
329	    /**
330	     * Maps a persisted owner to the {@link OwnerDto} returned by every rendered response, stamping
331	     * its {@code bulkSignupWarning} from the owner's stored {@code registrationDate} (see
332	     * {@link #bulkSignupWarning(LocalDate)}) and its {@code capacityWarning} from the owner's
333	     * {@code city} (see {@link #capacityWarning(String)}). This is the single definition of how an
334	     * owner becomes its response representation, shared by the read, idempotent-replay and create
335	     * responses, so all three derive the rendered fields identically rather than each copying the
336	     * mapping.
