444	    /**
445	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
446	     * The address is normalized in place (so a required-field check that follows rejects an
447	     * address blank after normalization), the required fields are checked, the telephone and
448	     * email are normalized in place, and the resulting owner is rejected when its derived
449	     * identity key already belongs to another owner. Each rule
450	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
451	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
452	     * to be mapped and saved.
453	     *
454	     * @param ownerFieldsDto the submitted owner fields, normalized in place
455	     */
456	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
457	        applyAddress(ownerFieldsDto);
458	        validateRequiredFields(ownerFieldsDto);
459	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
460	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
461	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
462	        rejectDuplicateIdentity(ownerFieldsDto);
463	        rejectCityAtCapacity(ownerFieldsDto.getCity());
464	        rejectDailyLimitExceeded(registrationDate);
465	    }
