467	    /**
468	     * Applies an owner's address to the submitted fields, normalizing it in place into the
469	     * canonical form stored and returned for the owner. This is the single intake step that owns
470	     * how a submitted address becomes an owner's stored address: it delegates every transform to
471	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
472	     * the results back onto {@code ownerFieldsDto}.
473	     *
474	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
475	     * is present the two structured lines are normalized in place and the flat {@code address} is
476	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
477	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
478	     * every rule that later reads {@code address} sees the structured value. When no structured
479	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
480	     * backward compatibility.
481	     *
482	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
483	     * blank after normalization in either form is rejected by the required-field check that
484	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
485	     * list of named intake steps and gives address handling one place to grow.
486	     *
487	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
488	     */
489	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
490	        String line1 = ownerFieldsDto.getAddressLine1();
491	        if (line1 != null && !line1.isBlank()) {
492	            String normalizedLine1 = normalizeAddress(line1);
493	            ownerFieldsDto.setAddressLine1(normalizedLine1);
494	            String line2 = ownerFieldsDto.getAddressLine2();
495	            if (line2 != null && !line2.isBlank()) {
496	                String normalizedLine2 = normalizeAddress(line2);
497	                ownerFieldsDto.setAddressLine2(normalizedLine2);
498	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
499	            } else {
500	                ownerFieldsDto.setAddressLine2(null);
501	                ownerFieldsDto.setAddress(normalizedLine1);
502	            }
503	        } else {
504	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
505	        }
506	    }
