508	    /**
509	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
510	     * falls on a business day. The date supplied on the request is used when present, otherwise the
511	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
512	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
513	     * is left unchanged. This single adjusted date
514	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
515	     * membership number's year segment, the per-day create limit) is computed against.
516	     *
517	     * A supplied registration date later than the server's current date is rejected with an
518	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
519	     *
520	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
521	     * @return the effective registration date rolled forward to the next business day
522	     */
523	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
524	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
525	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
526	            throw new InvalidFieldsException(List.of("registrationDate"));
527	        }
528	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
529	        return toBusinessDay(effective);
530	    }
531	
532	    /**
533	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
534	     * advanced, along with weekends, until it reaches the next non-holiday business day.
535	     */
536	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
537	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
538	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
539	        LocalDate.parse("2026-12-28"));
540	
541	    /**
542	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
543	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
544	     * date already on such a business day is returned unchanged.
545	     *
546	     * @param date the date to adjust
547	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
548	     */
549	    private LocalDate toBusinessDay(LocalDate date) {
550	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
551	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
552	                || PUBLIC_HOLIDAYS.contains(date)) {
553	            date = date.plusDays(1);
554	        }
555	        return date;
556	    }
