558	    /**
559	     * The maximum number of owners that may be created on a single day. Once this many owners
560	     * already carry today's {@code registrationDate}, no further owner may be created today.
561	     */
562	    private static final long DAILY_OWNER_LIMIT = 100L;
563	
564	    /**
565	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
566	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
567	     * date the new owner would be stored with, so owners are capped per business day. When the limit
568	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
569	     * advice renders as a 429 Too Many Requests response.
570	     *
571	     * @param registrationDate the adjusted business-day registration date of the owner being created
572	     */
573	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
574	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
575	            throw new DailyOwnerLimitExceededException(registrationDate);
576	        }
577	    }
