579	    /**
580	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
581	     * given date. This is the single definition of the per-day owner count, shared by the per-day
582	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
583	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
584	     *
585	     * @param registrationDate the adjusted business-day registration date to count owners against
586	     * @return the number of existing owners carrying that registration date
587	     */
588	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
589	        return this.clinicService.findAllOwners().stream()
590	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
591	            .count();
592	    }
