594	    /**
595	     * The number of owners that may carry a single day's {@code registrationDate} before that day
596	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
597	     * the create and read responses report {@code bulkSignupWarning} true for that date.
598	     */
599	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
600	
601	    /**
602	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
603	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
604	     * count is taken against the same adjusted date owners are stored with, mirroring the
605	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
606	     *
607	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
608	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
609	     */
610	    private boolean bulkSignupWarning(LocalDate registrationDate) {
611	        if (registrationDate == null) {
612	            return false;
613	        }
614	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
615	    }
