617	    /**
618	     * The maximum number of owners a single city may hold. Once a city already contains this
619	     * many owners, no further owner may be created in it.
620	     */
621	    private static final long CITY_OWNER_CAPACITY = 50L;
622	
623	    /**
624	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
625	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
626	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
627	     * which the exception advice renders as a 409 Conflict response.
628	     *
629	     * @param city the city of the owner being created
630	     */
631	    private void rejectCityAtCapacity(String city) {
632	        if (countOwnersInCity(city) >= CITY_OWNER_CAPACITY) {
633	            throw new CityCapacityExceededException(city);
634	        }
635	    }
636	
637	    /**
638	     * Counts the existing owners whose {@code city} equals the given city, compared
639	     * case-insensitively. This is the single definition of the per-city owner count, shared by the
640	     * hard capacity rejection ({@link #rejectCityAtCapacity(String)}) and the approaching-capacity
641	     * warning ({@link #capacityWarning(String)}), so both measure a city's occupancy identically.
642	     *
643	     * @param city the city to count owners against
644	     * @return the number of existing owners whose city matches
645	     */
646	    private long countOwnersInCity(String city) {
647	        return this.clinicService.findAllOwners().stream()
648	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
649	            .count();
650	    }
651	
652	    /**
653	     * The number of owners a city must already contain before it is flagged as approaching its
654	     * capacity limit. Once a city holds at least this many owners (but is not yet at
655	     * {@link #CITY_OWNER_CAPACITY}), the create and read responses report {@code capacityWarning}
656	     * true for owners in that city.
657	     */
658	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
659	
660	    /**
661	     * Reports whether the given city is approaching its capacity limit, i.e. whether it already
662	     * contains between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_CAPACITY}
663	     * minus one owners (40 to 49) inclusive. The count is taken the same way the hard rejection
664	     * counts a city's owners ({@link #countOwnersInCity(String)}). A {@code null} city never warns.
665	     *
666	     * @param city the city to test, or {@code null}
667	     * @return {@code true} when the city holds 40 to 49 owners, otherwise {@code false}
668	     */
669	    private boolean capacityWarning(String city) {
670	        if (city == null) {
671	            return false;
672	        }
673	        long count = countOwnersInCity(city);
674	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_CAPACITY;
675	    }
