677	    /**
678	     * Builds the unified {@code memberId} assigned to a newly created owner. The id is formatted as
679	     * {@code '<REGION><FY><HASH8><CHK>'}, concatenating (with no separators) the owner's region code
680	     * (see {@link Owner#getRegionCode()}, rendered {@code 'UNKNOWN'} when the owner has no known
681	     * region), the two-digit fiscal-year segment its business-day-adjusted {@code registrationDate}
682	     * falls in (see {@link Owner#fiscalYearSegment(LocalDate)}), its identity hash (see
683	     * {@link Owner#getIdentityHash()}, the first 8 upper-case hex characters of the SHA-256 digest
684	     * over the owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}) and
685	     * a single Luhn check digit (see {@link Owner#luhnCheckDigit(String)}) computed over the digits of
686	     * {@code <REGION><FY><HASH8>}. The composed base is then de-duplicated against existing owners
687	     * (see {@link #deduplicateMemberId(String)}). The base carries no sequence number, so two owners
688	     * sharing a region, fiscal year, telephone and last name resolve to the same base and are
689	     * separated only by de-duplication.
690	     *
691	     * @param owner the owner being created, whose fields the id is derived from
692	     * @return the formatted member id
693	     */
694	    private String memberIdFor(Owner owner) {
695	        String prefix = owner.getRegionCode()
696	            + Owner.fiscalYearSegment(owner.getRegistrationDate())
697	            + owner.getIdentityHash();
698	        return deduplicateMemberId(prefix + Owner.luhnCheckDigit(prefix));
699	    }
700	
701	    /**
702	     * Ensures the computed {@code memberId} is unique across existing owners. When the given base id
703	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
704	     * {@code n} of 2 or more that yields an id no existing owner already carries.
705	     *
706	     * @param baseCode the member id computed for the owner being created
707	     * @return the base id when it is already unique, otherwise the de-duplicated id
708	     */
709	    private String deduplicateMemberId(String baseCode) {
710	        Set<String> existing = this.clinicService.findAllOwners().stream()
711	            .map(Owner::getMemberId)
712	            .filter(Objects::nonNull)
713	            .collect(Collectors.toSet());
714	        if (!existing.contains(baseCode)) {
715	            return baseCode;
716	        }
717	        int n = 2;
718	        while (existing.contains(baseCode + "-" + n)) {
719	            n++;
720	        }
721	        return baseCode + "-" + n;
722	    }
