724	    /**
725	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
726	     * with the owner being created, compared case-insensitively. The count is taken before the
727	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
728	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
729	     *
730	     * @param firstName the first name of the owner being created
731	     * @param lastName the last name of the owner being created
732	     * @return the number of pre-existing owners sharing the same first and last name
733	     */
734	    private int countNamesakes(String firstName, String lastName) {
735	        return (int) this.clinicService.findAllOwners().stream()
736	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
737	                && lastName.equalsIgnoreCase(existing.getLastName()))
738	            .count();
739	    }
