741	    /**
742	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
743	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it does not share
744	     * an existing owner's identity key. A member that declared its household via
745	     * {@code sharesHousehold} is a deliberate addition to a known household, not a suspected
746	     * duplicate, so it is never flagged. Otherwise it is a possible duplicate when an existing owner
747	     * shares the Soundex code of its {@code lastName} and its {@code postcode} while carrying a
748	     * different identity key (see {@link #findPossibleDuplicate(Owner)}). When such an owner is
749	     * found, {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the
750	     * matching owner's id; otherwise {@code possibleDuplicate} is set {@code false} and no matching
751	     * id is recorded. An owner without a postcode can share no postcode and is never a possible
752	     * duplicate.
753	     *
754	     * @param owner the owner being created, already carrying its normalized telephone and postcode
755	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
756	     */
757	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
758	        owner.setPossibleDuplicate(false);
759	        owner.setPossibleDuplicateOf(null);
760	        if (sharesHousehold(ownerFieldsDto)) {
761	            return;
762	        }
763	        findPossibleDuplicate(owner).ifPresent(existing -> {
764	            owner.setPossibleDuplicate(true);
765	            owner.setPossibleDuplicateOf(existing.getId());
766	        });
767	    }
768	
769	    /**
770	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
771	     * duplicate: a non-deleted owner whose {@code lastName} shares the new owner's Soundex code (see
772	     * {@link Owner#soundex(String)}) and whose {@code postcode} matches, while carrying a different
773	     * identity key (see {@link Owner#identityKey(String, String, String)}). Requiring a differing
774	     * identity key keeps a hard duplicate — already rejected with 409 by
775	     * {@link #rejectDuplicateIdentity(OwnerFieldsDto)} — from also being flagged as a soft match, so
776	     * the two household members whose telephones differ (hence differing identity keys, but matching
777	     * Soundex and postcode) are exactly the soft matches surfaced here. This is the single definition
778	     * of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records
779	     * the outcome on the owner. An owner without a postcode can share no postcode and matches nothing,
780	     * so {@link java.util.Optional#empty()} is returned.
781	     *
782	     * @param owner the owner being created, already carrying its normalized telephone and postcode
783	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
784	     */
785	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
786	        if (owner.getPostcode() == null) {
787	            return java.util.Optional.empty();
788	        }
789	        String soundex = Owner.soundex(owner.getLastName());
790	        String identityKey = owner.getIdentityKey();
791	        return this.clinicService.findAllOwners().stream()
792	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
793	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
794	                && soundex.equals(Owner.soundex(existing.getLastName()))
795	                && owner.getPostcode().equals(existing.getPostcode()))
796	            .findFirst();
797	    }
