799	    /**
800	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
801	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
802	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
803	     * the names of every offending field, which the exception advice renders as a 400 response
804	     * with an {@code errors} array.
805	     *
806	     * @param ownerFieldsDto the submitted owner fields
807	     */
808	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
809	        List<String> missing = new ArrayList<>();
810	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
811	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
812	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
813	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
814	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
815	        if (!missing.isEmpty()) {
816	            throw new RequiredFieldsMissingException(missing);
817	        }
818	    }
