826	    /**
827	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
828	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
829	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
830	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
831	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
832	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
833	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
834	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
835	     *
836	     * @param telephone the submitted telephone value
837	     * @return the normalized E.164 telephone
838	     */
839	    private String normalizeTelephone(String telephone) {
840	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
841	        String e164;
842	        if (cleaned.startsWith("+")) {
843	            e164 = "+" + cleaned.substring(1);
844	        } else {
845	            String national = cleaned;
846	            if (national.startsWith("0")) {
847	                national = national.substring(1);
848	            }
849	            e164 = "+61" + national;
850	        }
851	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
852	            throw new InvalidFieldsException(List.of("telephone"));
853	        }
854	        validateNationalNumberLength(e164);
855	        return e164;
856	    }
857	
858	    /**
859	     * Validates the national-number length of an already syntactically valid E.164 telephone
860	     * against its country code. When the number carries a country code this application recognizes
861	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
862	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
863	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
864	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
865	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
866	     * that is not recognized carries no per-country length rule and is left to the general
867	     * 8-to-15-digit E.164 check.
868	     *
869	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
870	     */
871	    private void validateNationalNumberLength(String e164) {
872	        String countryCode = Owner.countryCodeOf(e164);
873	        if (countryCode == null) {
874	            return;
875	        }
876	        int nationalLength = e164.length() - 1 - countryCode.length();
877	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
878	            throw new InvalidFieldsException(List.of("telephone"));
879	        }
880	    }
881	
882	    /**
883	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
884	     * and a domain containing at least one dot, none of the parts holding whitespace or a
885	     * second {@code @}.
886	     */
887	    private static final java.util.regex.Pattern EMAIL_PATTERN =
888	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
889	
890	    /**
891	     * Disposable email domains an owner may not register with. An email whose domain (compared
892	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
893	     */
894	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
895	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
896	
897	    /**
898	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
899	     * accepted and returned unchanged. When present it must be a syntactically valid address
900	     * whose domain is not on the disposable-domain blocklist (see
901	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
902	     * present but syntactically invalid or on a disposable domain an
903	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
904	     * response naming the {@code email} field.
905	     *
906	     * @param email the submitted email value, or {@code null} when omitted
907	     * @return the lower-cased email, or {@code null} when none was supplied
908	     */
909	    private String normalizeEmail(String email) {
910	        if (email == null) {
911	            return null;
912	        }
913	        String trimmed = email.trim();
914	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
915	            throw new InvalidFieldsException(List.of("email"));
916	        }
917	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
918	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
919	            throw new InvalidFieldsException(List.of("email"));
920	        }
921	        return canonicalEmail(trimmed);
922	    }
923	
924	    /**
925	     * Reduces an email to the canonical form used both to store it and to compare it against
926	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
927	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
928	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
929	     * value read back off an existing owner without risk of rejecting it. This is the single
930	     * definition of email identity: two emails denote the same address exactly when they
931	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
932	     * an email already on an existing owner can be compared for equality after both pass through
933	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
934	     *
935	     * @param email the email to canonicalize, or {@code null} when none was supplied
936	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
937	     */
938	    private String canonicalEmail(String email) {
939	        if (email == null) {
940	            return null;
941	        }
942	        return email.trim().toLowerCase(java.util.Locale.ROOT);
943	    }
944	
945	    /**
946	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
947	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
948	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
949	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
950	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
951	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
952	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
953	     * 400 response naming the {@code postcode} field.
954	     *
955	     * @param postcode the submitted postcode, or {@code null} when omitted
956	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
957	     */
958	    private void validatePostcode(String postcode, String city) {
959	        if (postcode == null) {
960	            return;
961	        }
962	        if (!postcode.matches("^[0-9]{4}$")) {
963	            throw new InvalidFieldsException(List.of("postcode"));
964	        }
965	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
966	        if (range != null) {
967	            int value = Integer.parseInt(postcode);
968	            if (value < range[0] || value > range[1]) {
969	                throw new InvalidFieldsException(List.of("postcode"));
970	            }
971	        }
972	    }
973	
974	    /**
975	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
976	     * identity is its single derived identity key (see
977	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
978	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
979	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
980	     * owner carries the same identity key. The email-domain blocklist has already been applied when
981	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
982	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
983	     * name and postcode) but carry different telephones now have distinct identity keys and are not
984	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
985	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
986	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
987	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
988	     * deliberate household member and bypasses this block.
989	     *
990	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
991	     */
992	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
993	        if (sharesHousehold(ownerFieldsDto)) {
994	            return;
995	        }
996	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
997	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
998	        boolean taken = this.clinicService.findAllOwners().stream()
999	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1000	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
1001	        if (taken) {
1002	            throw new DuplicateIdentityException(identityKey);
1003	        }
1004	    }
1005	
1006	    /**
1007	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
1008	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
1009	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
1010	     * resolves to the same stable value automatically, without any explicit linking. An owner without
1011	     * a postcode belongs to no shared household and is left without a household identifier.
1012	     *
1013	     * @param owner the newly created owner, mutated in place with its household identifier
1014	     */
1015	    private void assignHousehold(Owner owner) {
1016	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
1017	    }
1018	
1019	    /**
1020	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
1021	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
1022	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
1023	     * every rule that treats a declared household member differently from an independent owner.
1024	     *
1025	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
1026	     * @return {@code true} when the request opted into sharing a household
1027	     */
1028	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
1029	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
1030	    }
1031	
1032	    /**
1033	     * Derives the stable {@code householdId} shared by every owner in the household identified by
1034	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
1035	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
1036	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
1037	     * postcode — regardless of creation order or address — resolve to the same identifier
1038	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
1039	     * returned.
1040	     *
1041	     * @param lastName the household's last name
1042	     * @param postcode the household's postcode, or {@code null} when the owner has none
1043	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
1044	     */
1045	    private String householdIdFor(String lastName, String postcode) {
1046	        if (postcode == null) {
1047	            return null;
1048	        }
1049	        return shaHex(householdKey(lastName, postcode), 12);
1050	    }
1051	
1052	    /**
1053	     * Builds the canonical household key that identifies the household a {@code lastName} and
1054	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
1055	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
1056	     * owner fields make up a household and how they are normalized;
1057	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
1058	     * owners in the same household resolve to the same key and therefore the same identifier.
1059	     *
1060	     * @param lastName the household's last name
1061	     * @param postcode the household's postcode
1062	     * @return the normalized household key
1063	     */
1064	    private String householdKey(String lastName, String postcode) {
1065	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
1066	    }
1067	
1068	    /**
1069	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
1070	     * string, the form used by the derived owner codes (for example the customer code and household
1071	     * identifier). Delegates to {@link Owner#shaHexPrefix(String, int)}, the single definition of the
1072	     * truncated upper-case hex derivation, so {@code hexChars} characters cover the leading
1073	     * {@code ceil(hexChars / 2)} bytes of the digest.
1074	     *
1075	     * @param input the string to hash
1076	     * @param hexChars the number of leading upper-case hex characters to return
1077	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
1078	     */
1079	    private String shaHex(String input, int hexChars) {
1080	        return Owner.shaHexPrefix(input, hexChars);
1081	    }
1082	
1083	    /**
1084	     * Returns the owners that belong to the household identified by the given {@code householdId},
1085	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
1086	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
1087	     * filters them out itself. The owners are taken from the current set, so after a create the
1088	     * result includes the newly persisted owner. An owner without a household (a {@code null}
1089	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
1090	     * definition of a household's members, shared by every rule that reasons about the owners
1091	     * sharing a household (the household-duplicate block and the household member count).
1092	     *
1093	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1094	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
1095	     */
1096	    private List<Owner> householdMembers(String householdId) {
1097	        if (householdId == null) {
1098	            return List.of();
1099	        }
1100	        return this.clinicService.findAllOwners().stream()
1101	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1102	            .collect(Collectors.toList());
1103	    }
1104	
1105	    /**
1106	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1107	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1108	     * is taken against the current set of owners, so after a create it reflects the household's size
1109	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1110	     * belongs to no shared household and yields {@code 0}.
1111	     *
1112	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1113	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1114	     */
1115	    private int countHouseholdMembers(String householdId) {
1116	        return householdMembers(householdId).size();
1117	    }
1118	
1119	    /**
1120	     * Stamps an owner with its household member count, the number of owners sharing its household
1121	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1122	     * household size (its membership factor and level) reads a populated count rather than the
1123	     * unstamped default. This is the single definition of hydrating an owner with its household
1124	     * member count, shared by the create and read paths that render an owner's derived values.
1125	     *
1126	     * @param owner the owner to stamp, mutated in place with its household member count
1127	     */
1128	    private void applyHouseholdMemberCount(Owner owner) {
1129	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1130	    }
1131	
1132	    /**
1133	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1134	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1135	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1136	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1137	     * reads a populated count, mirroring how the create and read paths render a member's derived
1138	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1139	     * members already in the household. When the owner joins an empty household — no household
1140	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1141	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1142	     *
1143	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1144	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1145	     */
1146	    private Integer householdMembershipLevelCap(String householdId) {
1147	        java.util.OptionalInt max = householdMembers(householdId).stream()
1148	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1149	            .peek(this::applyHouseholdMemberCount)
1150	            .mapToInt(Owner::getMembershipLevel)
1151	            .max();
1152	        return max.isPresent() ? max.getAsInt() + 1 : null;
1153	    }
1154	
1155	    /**
1156	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1157	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1158	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1159	     *
1160	     * @param value the value to collapse, or {@code null}
1161	     * @return the whitespace-collapsed value, never {@code null}
1162	     */
1163	    private String collapseWhitespace(String value) {
1164	        if (value == null) {
1165	            return "";
1166	        }
1167	        return value.trim().replaceAll("\\s+", " ");
1168	    }
1169	
1170	    /**
1171	     * Common street-type abbreviations expanded during address normalization, keyed by their
1172	     * upper-cased token.
1173	     */
1174	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1175	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1176	
1177	    /**
1178	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1179	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1180	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1181	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1182	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1183	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1184	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1185	     * everywhere an address is stored or compared.
1186	     *
1187	     * @param address the submitted address value, or {@code null}
1188	     * @return the normalized address, never {@code null}
1189	     */
1190	    private String normalizeAddress(String address) {
1191	        if (address == null) {
1192	            return "";
1193	        }
1194	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1195	        if (collapsed.isEmpty()) {
1196	            return "";
1197	        }
1198	        String[] tokens = collapsed.split(" ");
1199	        StringBuilder sb = new StringBuilder(collapsed.length());
1200	        for (int i = 0; i < tokens.length; i++) {
1201	            if (i > 0) {
1202	                sb.append(' ');
1203	            }
1204	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1205	        }
1206	        return sb.toString();
1207	    }
1208	}
